<script setup lang="ts">
const route=useRoute();const {data:response,error}=await useFetch<any>(`/api/tags/${route.params.slug}`);if(error.value)throw createError({statusCode:404,statusMessage:'标签不存在'});const data=computed(()=>response.value.data);useSeoMeta({title:()=>`# ${data.value.tag.name}`,description:()=>`${data.value.tag.name} 标签下的技术文章`})
</script>
<template><section class="tag-public"><header class="hero"><p class="eyebrow">TAG</p><h1># {{data.tag.name}}</h1><p class="lead">{{data.total}} 篇文章</p></header><div class="list"><NuxtLink v-for="post in data.items" :key="post.id" :to="`/blog/${post.id}`"><div><strong>{{post.title}}</strong><p>{{post.summary}}</p></div><time>{{new Date(post.publishedAt).toLocaleDateString('zh-CN')}}</time></NuxtLink><p v-if="!data.items.length">暂无已发布文章</p></div></section></template>
<style scoped>.tag-public{display:grid;gap:30px}.list{display:grid}.list>a{display:flex;justify-content:space-between;gap:20px;padding:20px 0;border-bottom:1px solid var(--color-border)}.list strong{font-size:16px}.list p{margin:7px 0 0;color:var(--color-text-secondary);font-size:12px;line-height:1.6}.list time{white-space:nowrap;color:var(--color-text-secondary);font-size:10px}</style>
